<?php if($settings['flags']['venues']):?><section id="venues"><p class="eyebrow"><?=me(__('manor.find_your_setting'))?></p><h2><?=me($settings['venues_title'])?></h2><div class="grid"><?php foreach($units as $u):$d=json_decode($u['data'],true);try{\App\Manor\Settings::mode($u['mode']);}catch(\DomainException){continue;}if(in_array($u['mode'],['BUILDING','FLOOR'],true))continue;?><article class="venue <?= $u['mode']==='ENTIRE_PROPERTY'?'exclusive-card':'' ?>"><?=media($settings,$u['id'],true)?><h3><?=me($u['name'])?></h3><p><?=me($d['description']??'Details to be confirmed by management.')?></p><?php if($settings['flags']['public_pricing']&&($d['pricing_mode']??'')==='SHOW_PRICE'&&isset($d['price'])):?><p><?=me(__('manor.from'))?> <?=money(\App\Manor\Rules::pence((string)$d['price']))?></p><?php elseif($settings['flags']['price_on_request']&&($d['pricing_mode']??'PRICE_ON_REQUEST')==='PRICE_ON_REQUEST'):?><p class="muted"><?=me(__('manor.price_on_request'))?></p><?php endif?><?php if($settings['flags']['enquiries']):?><a class="text-link" href="/manor/enquire?unit=<?=me($u['id'])?>"><?=me(__('manor.enquire_about_this_space'))?></a><?php endif?></article><?php endforeach?></div></section><?php endif?>
